import PohButton from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import { showModal } from '@ui-kit/Modal';

import EditPaymentModal from './EditPaymentModal';
import EditReceiptModal, { IEditReceiptModalProps } from './EditReceiptModal';
import { IEditReceiptParticipationModalProps } from './EditReceiptParticipationModal';
import EditReceiptParticipationModal from './EditReceiptParticipationModal';
import ViewReceiptModal from './ViewReceiptModal';
import { IHikingData } from '../../@types/hiking.types';
import { IHikingPayment, IHikingReceipt } from '../../@types/hikingFinances.types';

type editOrAddReceiptAsyncProps = Omit<IEditReceiptModalProps, 'onAdd' | 'onEdit' | 'onCancel'>;
export function editOrAddReceiptAsync(props: editOrAddReceiptAsyncProps): Promise<IHikingReceipt> {
  return new Promise((resolve) => {
    showModal({
      title: props.receipt ? 'Редактирование чека' : 'Добавление чека',
      size: 'lg',
      children: (closeHandler: () => void) => (
        <EditReceiptModal
          {...props}
          onAdd={(bp) => {
            resolve(bp);
            closeHandler();
          }}
          onEdit={(bp) => {
            resolve(bp);
            closeHandler();
          }}
        />
      ),
    });
  });
}
type editReceiptParticipationProps = Omit<IEditReceiptParticipationModalProps, 'onChange'>;
export function editReceiptParticipationAsync(
  props: editReceiptParticipationProps,
): Promise<IHikingReceipt> {
  return new Promise((resolve) => {
    showModal({
      title: 'Долевое участие 🍕',
      children: (closeHandler: () => void) => (
        <EditReceiptParticipationModal
          {...props}
          onChange={(bp) => {
            resolve(bp);
            closeHandler();
          }}
        />
      ),
    });
  });
}

export function viewReceipt(receipt: IHikingReceipt, hikingData: IHikingData) {
  showModal({
    size: 'lg',
    title: (
      <>
        {' '}
        <PohButton
          className="float-end"
          icon={IconsEnum.open}
          onClick={() => window.open(`/hiking/${hikingData.id}/finances/${receipt.id}`)}
        />
        {receipt.name}
      </>
    ),
    children: (_closeHandler: () => void) => (
      <ViewReceiptModal receipt={receipt} hikingData={hikingData} />
    ),
  });
}

export function editOrAddPaymentAsync(
  payment: IHikingPayment,
  hikingData: IHikingData,
): Promise<IHikingPayment> {
  return new Promise((resolve) => {
    showModal({
      title: payment.id > 0 ? 'Редактирование взноса' : 'Добавление взноса',
      style: { minWidth: 420, width: 600 },
      children: (closeHandler: () => void) => (
        <EditPaymentModal
          payment={payment}
          hikingData={hikingData}
          onSave={(bp) => {
            resolve(bp);
            closeHandler();
          }}
          onCancel={closeHandler}
        />
      ),
    });
  });
}
