import React from 'react';

import clsx from 'clsx';

import { formatFinance } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';
import PohAva from '@ui-kit/Ava';
import PohButton, { ButtonSize } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import styles from './styles.module.less';
import QRIcon from '../../../../img/svg/qr.inline.svg';
import { IHikingData } from '../../@types/hiking.types';
import { IHikingReceipt, IHikingReceiptCategory } from '../../@types/hikingFinances.types';
interface IHikingFinanceReceiptItemProps {
  hikingData: IHikingData;
  receipt: IHikingReceipt;
  categories: IHikingReceiptCategory[];
  onDelete?: (receipt: IHikingReceipt) => void;
  onEdit?: (receipt: IHikingReceipt) => void;
  onEditParts?: (receipt: IHikingReceipt) => void;
}

const HikingFinanceReceiptItem: React.FC<IHikingFinanceReceiptItemProps> = ({
  hikingData,
  receipt,
  categories,
  onDelete,
  onEdit,
  onEditParts,
}) => {
  const category = receipt.idCategory ? categories.find((x) => x.id === receipt.idCategory) : null;
  return (
    <PohRow>
      <PohCol xs={3} sm={2} md={1} className="">
        <div
          className={clsx(styles.hikingReceiptPhoto, 'img-rounded')}
          style={{
            backgroundImage: `url(${receipt.images[100] ?? `'http://chart.apis.google.com/chart?cht=qr&chs=300x300&chl=${receipt.qr_code}'`})`,
          }}
        >
          {receipt.qr_code && <QRIcon width="80%" height="80%" style={{ margin: '10%' }} />}
          <div
            className={clsx(styles.hikingReceiptOwnerAvatar, 'img-rounded')}
            title={[receipt.user.name, receipt.user.surname].join(' ')}
            style={{ backgroundImage: `url(${receipt.user.photo})` }}
          />
        </div>
      </PohCol>
      <PohCol xs={9} sm={10} md={11}>
        <PohRow>
          <PohCol sm={9}>
            <PohRow as="h5" className="list-group-item-heading mb-0">
              <PohCol xs={12} sm={6} md={4} className="text-danger d-flex">
                <span>
                  {!receipt.totalInCurrency && formatFinance(receipt.total)}
                  {receipt.totalInCurrency ? (
                    <small className="text-info">
                      {formatFinance(receipt.totalInCurrency, 2, receipt.currency?.symbol)}
                      <small>
                        &thinsp;×&thinsp;{round(receipt.total / receipt.totalInCurrency, 2)}
                      </small>
                      &thinsp;=&thinsp;
                      <strong className="text-danger">{formatFinance(receipt.total)}</strong>
                    </small>
                  ) : null}
                  {receipt.participation && (
                    <small
                      className="text-warning"
                      title={receipt.participation.map((p) => p.fullName).join('\n')}
                    >
                      &nbsp;÷&nbsp;на&nbsp;{receipt.participation.length}-x&nbsp;&nbsp;&nbsp;
                    </small>
                  )}
                </span>
                {receipt.participation && (
                  <span className="d-inline-block ms-auto">
                    {hikingData.hikers
                      .filter((h) => receipt.participation?.find((p) => p.id === h.idUser))
                      .map((h) => (
                        <PohAva
                          key={h.idUser}
                          alt={h.name}
                          src={h.photo[50]}
                          width={16}
                          style={{ marginLeft: -4 }}
                        />
                      ))}
                  </span>
                )}
              </PohCol>
              <PohCol xs={12} sm={6} md={8} className="text-muted">
                {receipt.name}
              </PohCol>
            </PohRow>
            <PohRow>
              <PohCol xs={12} sm={6} md={4} className="text-muted">
                <PohRow as="small" className="list-group-item-text">
                  <PohCol className="text-muted" xs={6} sm={12}>
                    {receipt.date.toLocaleString(undefined, {
                      dateStyle: 'short',
                      timeStyle: 'short',
                    })}
                  </PohCol>
                  <PohCol xs={6} sm={12}>
                    {[receipt.user.name, receipt.user.surname].join(' ')}
                  </PohCol>
                </PohRow>
              </PohCol>
              <PohCol xs={12} sm={6} md={8} className="text-muted">
                {category && (
                  <span
                    style={{
                      display: 'inline-block',
                      padding: '0 4px',
                      marginTop: 4,
                      color: category.color,
                      borderRadius: 4,
                      fontSize: '12px',
                      lineHeight: '16px',
                      border: `1px solid ${category.color}`,
                    }}
                  >
                    {category.name}
                  </span>
                )}
              </PohCol>
            </PohRow>
          </PohCol>
          <PohCol sm={3}>
            <aside className="d-flex align-items-center justify-content-end">
              {onEditParts && (
                <PohButton
                  size={ButtonSize.Small}
                  icon={true}
                  onClick={(e) => {
                    e.stopPropagation();
                    onEditParts(receipt);
                  }}
                  className="ms-2"
                >
                  🍕
                </PohButton>
              )}
              {onDelete && (
                <PohButton
                  size={ButtonSize.Small}
                  icon={IconsEnum.trash}
                  onClick={(e) => {
                    e.stopPropagation();
                    onDelete(receipt);
                  }}
                  className="ms-2"
                />
              )}
              {onEdit && (
                <PohButton
                  size={ButtonSize.Small}
                  icon={IconsEnum.edit}
                  onClick={(e) => {
                    e.stopPropagation();
                    onEdit(receipt);
                  }}
                  className="ms-2"
                />
              )}
            </aside>
          </PohCol>
        </PohRow>
      </PohCol>
    </PohRow>
  );
};

export default HikingFinanceReceiptItem;
